      "event": "Integration with the College's student records system encounters delays, preventing go-live by 2027-01-11.",
      "effect": "Students cannot use the signature service during the first day of spring enrollment.",
      "assumptions": [],
      "owner_role": "Integration lead",
      "trigger": "API integration work package exceeds its low estimate of 6 days without connecting to the REST API.",
      "responses": [
        "Prioritize core REST API endpoints required for enrollment before secondary features.",
        "Confirm test environment access with the College's IT team this week."
