        "REQ-0008",
        "REQ-0012"
      ],
      "affects": [
        "REQ-0008",
        "REQ-0012"
      ]
    },
    {
      "condition": "Record migration under REQ-0007 is scheduled with a high estimate of 20 days and a target date of 2027-02-28, coming after the 2027-01-11 go-live date.",
      "event": "Historic records are not fully migrated and reconciled by 2027-02-28.",
      "effect": "Users cannot access signed records held in the current tool during the post-go-live transition window.",
      "assumptions": [
        "A certified partner is available to manage complex historic record migrations and reconciliation."
      ],
      "owner_role": "Migration lead",
      "trigger": "Migration work package 2.1 passes 10 days without completing data mapping.",
      "responses": [
        "Engage the migration partner immediately to verify data formats.",
        "Migrate the most frequently accessed forms first."
      ],
      "residual_exposure": "A temporary gap in historic record availability until migration completes.",
      "evidence_src_ids": [
        "REQ-0007",
        "REQ-0012"
      ],
      "affects": [
        "REQ-0007"
      ]
    }
